const items = [{
  name: "potion",
  usable: true
}, {
  name: "rusty sword",
  usable: false
}, {
  name: "shield",
  usable: true
}];


function searchItems() {
  const ul = document.querySelector("ul");
  ul.innerHTML = "";
  for (let i = 0; i < items.length; i++) {
    if (show(items[i])) {
      const li = document.createElement("li");
      li.innerHTML = items[i].name;
      ul.appendChild(li);
    }
  }
}

function show(item){
  const input = document.querySelector("input");
  const usableOnly = document.querySelectorAll("input")[1];
  return (input.value === "" || item.name.indexOf(input.value) > -1) && (!
        usableOnly.checked || item.usable);
}
searchItems();

